    ["<Assistant_Title1>First Glimpse of the Hidden</>\n<Assistant_Title2>Achievement Category: </>TRPG-Order World\n<Assistant_Title2>Unlock Condition: </>Complete the first Hidden Space"] = "<Assistant_Title1>РџРµСЂРІС‹Р№ РІР·РіР»СЏРґ РЅР° С‚Р°Р№РЅСѓ</>\n<Assistant_Title2>РљР°С‚РµРіРѕСЂРёСЏ РґРѕСЃС‚РёР¶РµРЅРёСЏ: </>РќР Р вЂ” РњРёСЂ РџРѕСЂСЏРґРєР°\n<Assistant_Title2>РЈСЃР»РѕРІРёРµ РїРѕР»СѓС‡РµРЅРёСЏ: </>Р—Р°РІРµСЂС€РёС‚Рµ СЃРІРѕРµ РїРµСЂРІРѕРµ С‚Р°Р№РЅРѕРµ РїСЂРѕСЃС‚СЂР°РЅСЃС‚РІРѕ",
    ["Text Board - Bard - 1st Sword Text"] = "РўРµРєСЃС‚РѕРІР°СЏ РґРѕСЃРєР° вЂ” Р‘Р°СЂРґ вЂ” РўРµРєСЃС‚ 1-РіРѕ РјРµС‡Р°",
